.mark { width: 78px; height: 78px; flex: none; }
.mark path { fill: none; stroke-width: 5; stroke-linecap: round; }
.mark-strokes path { stroke: var(--ink); }
.mark-slash { stroke: var(--vermilion); }
h1 { font: 700 54px/0.95 var(--serif); letter-spacing: 0; }
.strap { font-style: italic; font-size: 17px; max-width: 36ch; line-height: 1.35; margin-top: 8px; color: var(--ink-2); }

.run { display: grid; grid-template-columns: auto auto; gap: 6px 36px; }
.run dt { font-style: italic; font-size: 14px; color: var(--ink-2); line-height: 1.2; }
.run dd { font-family: var(--mono); font-size: 15px; font-weight: 500; }

.live {
  display: inline-block; width: 9px; height: 9px; margin-right: 8px; border-radius: 50%;
  background: var(--ink); vertical-align: 1px;
  animation: blink 1.2s steps(2, jump-none) infinite;
}
@keyframes blink { 50% { opacity: 0.15; } }

.notice {
  margin-top: 16px; padding: 10px 14px;
  border: 1px solid var(--rule); border-left-width: 6px;
  font-size: 16px; max-width: 110ch;
}
.data-source {
  margin-top: 10px;
  font: 400 14px/1.45 var(--mono);
  color: var(--ink-2);
}
.run-picker {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-top: 14px;
  padding: 10px 0;
  border-top: 1px solid var(--rule-soft);
  border-bottom: 1px solid var(--rule-soft);
}
.run-picker label {
  font: italic 400 16px/1.2 var(--serif);
  color: var(--ink-2);
}
.run-picker select {
  max-width: min(680px, 100%);
  border: 1px solid var(--rule);
  background: var(--paper);
  color: var(--ink);
  font: 500 14px/1.2 var(--mono);
  padding: 6px 28px 6px 8px;
}
.picker-note { font-size: 14.5px; color: var(--ink-2); font-style: italic; }
body.unread .sheet > section, body.unread .run, body.unread .foot { display: none; }

/* ---------- headline and budget ---------- */

.sheet > .summary { display: grid; grid-template-columns: minmax(380px, 5fr) 7fr; margin-top: 26px; }
.headline { padding-right: 40px; border-right: 1px solid var(--rule); }
.budget { padding-left: 40px; }

.big { font-size: 84px; line-height: 1; font-weight: 500; letter-spacing: 0; margin: 10px 0 12px; }
.big .none { font: italic 400 40px/2.1 var(--serif); letter-spacing: 0; color: var(--ink-2); }
.marks { display: flex; align-items: center; flex-wrap: wrap; gap: 6px 12px; font-size: 16px; }
.marks svg { height: 28px; }
.marks path { fill: none; stroke: var(--ink); stroke-width: 2.6; stroke-linecap: round; }
.marks span { margin-left: 4px; }
.compare { margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--rule-soft); font-size: 16px; line-height: 1.4; }
.compare .base { display: block; }
.compare .base b { font-size: 22px; font-weight: 600; }
.compare > span:last-child:not(.base) { display: block; margin-top: 4px; font-weight: 700; font-size: 19px; }

.budget-figs { display: flex; justify-content: space-between; align-items: baseline; margin: 10px 0 12px; font-size: 17px; }
.budget-figs b { font-size: 34px; font-weight: 500; letter-spacing: 0; margin-right: 6px; }
.bar {
  position: relative; display: flex; height: 44px;
  border: 2px solid var(--rule); background: var(--paper);
}
.seg { background: var(--ink); border-right: 2px solid var(--paper); min-width: 3px; }
.seg.stop { background: var(--vermilion); }
.seg.run { background: var(--ink-2); border-right: 2px dotted var(--paper); }
.bar .limit { display: none; position: absolute; top: -8px; bottom: -8px; width: 0; border-left: 2px dashed var(--vermilion); }
.bar.is-over .limit { display: block; }
.bar-scale { display: flex; justify-content: space-between; font: 400 14px/1.6 var(--mono); margin-top: 4px; }
.bar-key { font-size: 15px; font-style: italic; color: var(--ink-2); margin-top: 6px; }
.key-stop { color: var(--vermilion); }

/* ---------- integrations ---------- */

.sheet > .integrations {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  margin-top: 28px; border-top: 1px solid var(--rule); border-bottom: 1px solid var(--rule);
}
.int { display: flex; gap: 12px; padding: 10px 16px 10px 0; align-items: flex-start; }
.int + .int { padding-left: 16px; border-left: 1px solid var(--rule-soft); }
.int p { font-size: 16px; line-height: 1.3; }
.int .state { font-family: var(--mono); font-size: 14px; font-weight: 600; margin-left: 4px; }
.int .detail { display: block; font-size: 14.5px; font-style: italic; color: var(--ink-2); }
.box { flex: none; width: 15px; height: 15px; margin-top: 4px; border: 2px solid var(--ink); position: relative; }
.int-ok .box { background: var(--ink); }
.int-off b, .int-off .state { color: var(--ink-2); font-weight: 400; }
.int-off .box { border-color: var(--ink-2); }
.int-missing .box { border-style: dashed; }
/* broken: a crossed box, in ink */
.int-error .box::before, .int-error .box::after {
  content: ''; position: absolute; left: -3px; right: -3px; top: 4px; border-top: 2px solid var(--ink);
}
.int-error .box::before { transform: rotate(45deg); }
.int-error .box::after { transform: rotate(-45deg); }
.int-error .state, .int-missing .state { text-decoration: underline; text-underline-offset: 3px; }

