.ledger tbody tr:first-child.group-start td { border-top: 0; }
.ledger .fig { font-size: 14.5px; }
.l-task { max-width: 34ch; }
.l-task-id { display: block; font: 600 13px/1.35 var(--mono); color: var(--ink-2); }
.l-note { display: block; font: italic 400 13.5px/1.35 var(--serif); color: var(--ink-2); letter-spacing: 0; }
.l-links a, .evidence-id { margin-right: 12px; white-space: nowrap; }
.evidence-id { display: inline-block; color: var(--ink-2); }
.evidence-id code {
