  child.on('exit', (code) => {
    if (!out.includes('dashboard http')) reject(new Error(`dashboard exited ${code} stdout=${out} stderr=${err}`));
  });
});
done.then((result) => console.log(result)).catch((error) => { child.kill('SIGTERM'); console.error(error); process.exit(1); });
